head.script:
scwin.t1_onclick = function(e) {
    widgetContainer1.resizeWidget("widget0", 2, 2);
};
scwin.trigger2_onclick = function(e) {
    widgetContainer1.resizeWidget("widget0", 2, 2, {
        "force": true
    });
};
scwin.__parseStyle = function(style, type, append) {
    var value = parseFloat(style);
    return value * append + type;
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getDomById($p.id + 'widgetContainer1_widget0').style.width == widthInit;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getDomById($p.id + 'widgetContainer1_widget0').style.height == heightInit;
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getDomById($p.id + 'widgetContainer1_widget0').style.width >= scwin.__parseStyle(widthInit, '%', 2);
}
scwin.checkVal4 = function() {
    return WebSquare.wUnit.getDomById($p.id + 'widgetContainer1_widget0').style.height >= scwin.__parseStyle(heightInit, '%', 2);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 'resizeWidget('widget0', 2, 2)'버튼을 클릭한다.
    //1. Run the sample file and click the 'resizeWidget (' widget0 ', 2, 2)' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('t1').click()");
    //Verify step 1. 위젯의 사이즈가 변경되지 않는다.(정상)
    //1. Widget size does not change (normal)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    //Verify step 2. 위젯의 사이즈가 2,2로 변경된다.
    //2. The size of the widget is changed to 2,2.
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    widgetContainer1.addWidgets({
        title: "widget0",
        src: null,
        scope: true,
        x: 0,
        y: 0,
        unitWidth: 1,
        unitHeight: 1
    });
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 06-Feb-2018
    window.widthInit = WebSquare.wUnit.getDomById($p.id + "widgetContainer1_widget0").style.width;
    window.heightInit = WebSquare.wUnit.getDomById($p.id + "widgetContainer1_widget0").style.height;
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
